Search the Bibliography
Use the interactive database below to search and filter through the bibliography of primary sources.

bibliography = FileAttachment("data/bibliography.json").json()

// Extract all works with author info for easier filtering
allWorks = bibliography.authors.flatMap(author =&gt;
  author.works.map(work =&gt; ({
    ...work,
    authorName: author.name,
    authorId: author.id,
    century: author.century,
    deathDate: author.deathDate,
    deathLocation: author.deathLocation,
    hasEditions: work.editions && work.editions.length &gt; 0,
    hasTranslations: work.translations && work.translations.length &gt; 0,
    hasManuscripts: work.manuscripts && work.manuscripts.length &gt; 0
  }))
)

// Search input
viewof searchTerm = Inputs.search(allWorks, {
  placeholder: "Search by author, title, edition, or translation...",
  query: (work, term) =&gt; {
    const searchStr = term.toLowerCase();
    return (
      work.authorName.toLowerCase().includes(searchStr) ||
      work.title.toLowerCase().includes(searchStr) ||
      (work.titleTranslation && work.titleTranslation.toLowerCase().includes(searchStr)) ||
      work.editions.some(ed =&gt; ed.citation.toLowerCase().includes(searchStr)) ||
      work.translations.some(tr =&gt; tr.citation.toLowerCase().includes(searchStr))
    );
  }
})

// Filter controls
viewof centuryFilter = Inputs.select(
  ["All", "3rd/9th", "4th/10th", "5th/11th"],
  {label: "Century:", value: "All"}
)

viewof typeFilter = Inputs.select(
  ["All", "discursive", "isnad", "reconstruction", "uncertain"],
  {label: "Work Type:", value: "All", format: x =&gt; x === "All" ? "All Types" : x === "isnad" ? "Isnād-based" : x.charAt(0).toUpperCase() + x.slice(1)}
)

viewof availabilityFilter = Inputs.select(
  ["All", "has-editions", "has-translations", "has-manuscripts"],
  {label: "Availability:", value: "All", format: x =&gt; ({
    "All": "All Works",
    "has-editions": "Has Editions",
    "has-translations": "Has Translations",
    "has-manuscripts": "Has Manuscripts"
  })[x]}
)

// Apply filters
filteredWorks = {
  let works = searchTerm;

  if (centuryFilter !== "All") {
    works = works.filter(w =&gt; w.century === centuryFilter);
  }

  if (typeFilter !== "All") {
    works = works.filter(w =&gt; w.type === typeFilter);
  }

  if (availabilityFilter === "has-editions") {
    works = works.filter(w =&gt; w.hasEditions);
  } else if (availabilityFilter === "has-translations") {
    works = works.filter(w =&gt; w.hasTranslations);
  } else if (availabilityFilter === "has-manuscripts") {
    works = works.filter(w =&gt; w.hasManuscripts);
  }

  return works;
}

// Results count
html`&lt;p style="color: #adb5bd; margin: 1rem 0;"&gt;
  Showing &lt;strong&gt;${filteredWorks.length}&lt;/strong&gt; of &lt;strong&gt;${allWorks.length}&lt;/strong&gt; works
&lt;/p&gt;`
























































filteredWorks.map(work =&gt; {
  const typeColors = {
    discursive: "#f8f9fa",
    isnad: "#0dcaf0",
    reconstruction: "#ffc107",
    uncertain: "#dc3545"
  };

  const typeLabels = {
    discursive: "Discursive Work",
    isnad: "Isnād-based Work",
    reconstruction: "Reconstruction",
    uncertain: "Uncertain Attribution"
  };

  const typeColor = typeColors[work.type] || "#f8f9fa";
  const typeLabel = typeLabels[work.type] || work.type;
  const textColor = work.type === "discursive" || work.type === "isnad" || work.type === "reconstruction" ? "#000" : "#fff";

  return html`
    &lt;div class="bib-card" style="background-color: #212529; border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; padding: 1.5rem; margin-bottom: 1.5rem;"&gt;
      &lt;div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 1rem;"&gt;
        &lt;div style="flex: 1;"&gt;
          &lt;h4 style="margin: 0 0 0.5rem 0; color: #f8f9fa;"&gt;${work.title}&lt;/h4&gt;
          &lt;p style="margin: 0; color: #adb5bd; font-size: 0.95rem;"&gt;
            &lt;strong&gt;${work.authorName}&lt;/strong&gt; (d. ${work.deathDate})
          &lt;/p&gt;
        &lt;/div&gt;
        &lt;span style="background-color: ${typeColor}; color: ${textColor}; padding: 0.25rem 0.75rem; border-radius: 4px; font-size: 0.875rem; font-weight: 500; white-space: nowrap; margin-left: 1rem;"&gt;
          ${typeLabel}
        &lt;/span&gt;
      &lt;/div&gt;

      ${work.editions && work.editions.length &gt; 0 ? html`
        &lt;div style="margin-top: 1rem;"&gt;
          &lt;h5 style="color: #0dcaf0; font-size: 1rem; margin-bottom: 0.5rem;"&gt;
            📚 Editions (${work.editions.length})
          &lt;/h5&gt;
          &lt;ol style="margin: 0; padding-left: 1.5rem;"&gt;
            ${work.editions.map(ed =&gt; html`
              &lt;li style="margin-bottom: 0.5rem; color: #adb5bd; font-size: 0.9rem;"&gt;
                ${ed.citation}
                ${ed.link ? html` &lt;a href="${ed.link}" target="_blank" style="color: #0dcaf0; text-decoration: none;"&gt;[link]&lt;/a&gt;` : ''}
              &lt;/li&gt;
            `)}
          &lt;/ol&gt;
        &lt;/div&gt;
      ` : ''}

      ${work.translations && work.translations.length &gt; 0 ? html`
        &lt;div style="margin-top: 1rem;"&gt;
          &lt;h5 style="color: #0dcaf0; font-size: 1rem; margin-bottom: 0.5rem;"&gt;
            🌐 Translations (${work.translations.length})
          &lt;/h5&gt;
          &lt;ol style="margin: 0; padding-left: 1.5rem;"&gt;
            ${work.translations.map(tr =&gt; html`
              &lt;li style="margin-bottom: 0.5rem; color: #adb5bd; font-size: 0.9rem;"&gt;
                ${tr.language ? `[${tr.language}] ` : ''}${tr.citation}
                ${tr.link ? html` &lt;a href="${ed.link}" target="_blank" style="color: #0dcaf0; text-decoration: none;"&gt;[link]&lt;/a&gt;` : ''}
              &lt;/li&gt;
            `)}
          &lt;/ol&gt;
        &lt;/div&gt;
      ` : ''}

      ${work.manuscripts && work.manuscripts.length &gt; 0 ? html`
        &lt;div style="margin-top: 1rem;"&gt;
          &lt;h5 style="color: #ffc107; font-size: 1rem; margin-bottom: 0.5rem;"&gt;
            📜 Manuscripts (${work.manuscripts.length})
          &lt;/h5&gt;
          &lt;ol style="margin: 0; padding-left: 1.5rem;"&gt;
            ${work.manuscripts.map(ms =&gt; html`
              &lt;li style="margin-bottom: 0.5rem; color: #adb5bd; font-size: 0.9rem;"&gt;${ms}&lt;/li&gt;
            `)}
          &lt;/ol&gt;
        &lt;/div&gt;
      ` : ''}
    &lt;/div&gt;
  `;
})
